params.script_inline:
import sys, json, time, urllib.request, urllib.error, urllib.parse, socket

# The `weather` tool of this hive (GH #1260): one place in, the forecast of that
# place out, from Open-Meteo -- free and without a key, so the tool needs no
# grant and no credential lane. Two GETs: the geocoder names the place, the
# forecast answers for its coordinates. Both endpoints are params, so a test
# points them at a local stub and an operator at a mirror; nothing here knows a
# host.
#
# WHY A CODE CELL. Two calls and a table of weather codes are not a new cell
# type; the memory hive's embedder is the precedent for HTTP out of a `code`
# cell (`sandbox.network: allow`, urllib, its own operation timeout).

STARTED = time.monotonic()

doc = json.load(sys.stdin)
P = doc.get("params") or {}
hop = ((doc.get("envelope") or {}).get("header") or {}).get("hop") or {}
turns = (doc.get("body") or {}).get("messages") or []
call = next((m for m in turns if isinstance(m, dict) and m.get("type") == "tool_call"), {})
CALL_ID = str(call.get("id") or hop.get("tool_call_id") or "")


def knob(key, default):
    """A param left null or blank is 'not configured', not a crash."""
    v = P.get(key)
    if v is None or (isinstance(v, str) and not v.strip()):
        return default
    return v


def knob_int(key, default):
    try:
        return int(knob(key, default))
    except (TypeError, ValueError):
        return default


GEOCODE = str(knob("geocode_endpoint", "https://geocoding-api.open-meteo.com/v1/search"))
FORECAST = str(knob("forecast_endpoint", "https://api.open-meteo.com/v1/forecast"))
USER_AGENT = str(knob("user_agent", "meclaw weather"))
LANGUAGE = str(knob("default_language", "de"))
MAX_DAYS = 7

# AGENTS rule 12: the I/O bounds itself against the cell's OWN operation
# timeout. Both requests share one deadline, and a reserve stays for the spawn
# and the final write: a process the substrate kills answers nothing, and a
# tool round waiting on that answer stalls until its backstop.
EXTERNAL_TIMEOUT_S = knob_int("external_timeout_ms", 15000) / 1000.0
DEADLINE_RESERVE_S = 1.0
MIN_ATTEMPT_S = 0.5
DEADLINE = STARTED + max(MIN_ATTEMPT_S, EXTERNAL_TIMEOUT_S - DEADLINE_RESERVE_S)


def emit(text, error_code=None):
    """ONE tool_result turn on the hive's one lane. A refusal is an ordinary
    result with `hop.error_code` and an error object as its text -- never an
    empty answer: an empty result is exactly what the curator's speaker rule
    reads as unspeakable, and silence would stall the round."""
    header = {"operation": "weather", "tool_call_id": CALL_ID}
    if error_code:
        header["error_code"] = error_code
    sys.stdout.write(json.dumps({
        "header": header,
        "messages": [{"origin": "tool", "type": "tool_result", "id": CALL_ID,
                      "text": text}]}, ensure_ascii=False))
    sys.exit(0)


def refuse(code, message):
    emit(json.dumps({"error": message, "error_code": code}, ensure_ascii=False), code)


class Upstream(Exception):
    def __init__(self, code, message):
        super().__init__(message)
        self.code = code


def get_json(endpoint, query):
    """GET `endpoint?query` within what is left of the deadline. Every failure
    is one of three named codes: `timeout` (the bound elapsed), `io_error` (no
    connection at all) and `upstream_error` (an answer that is not a 2xx JSON
    document)."""
    remaining = DEADLINE - time.monotonic()
    if remaining < MIN_ATTEMPT_S:
        raise Upstream("timeout", "no time left for %s" % endpoint)
    url = endpoint + ("&" if "?" in endpoint else "?") + urllib.parse.urlencode(query)
    req = urllib.request.Request(url, headers={"User-Agent": USER_AGENT,
                                               "Accept": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=remaining) as resp:
            raw = resp.read()
    except urllib.error.HTTPError as e:
        raise Upstream("upstream_error", "the weather service answered HTTP %s" % e.code)
    except (socket.timeout, TimeoutError) as e:
        raise Upstream("timeout", "the weather service did not answer in time")
    except urllib.error.URLError as e:
        if isinstance(e.reason, (socket.timeout, TimeoutError)):
            raise Upstream("timeout", "the weather service did not answer in time")
        raise Upstream("io_error", "the weather service is unreachable (%s)"
                       % type(e.reason).__name__)
    except OSError as e:
        raise Upstream("io_error", "the weather service is unreachable (%s)" % type(e).__name__)
    try:
        return json.loads(raw.decode("utf-8"))
    except Exception:
        raise Upstream("upstream_error", "the weather service answered no JSON")


# The words a voice says -- WMO weather codes (the `weather_code` Open-Meteo
# returns) and the few phrases of the summary -- are language data and live in
# `params.condition_lang`, one table per language. A language the table does
# not carry reads English; a code no table names is said as its number.
LANG_DATA = P.get("condition_lang") if isinstance(P.get("condition_lang"), dict) else {}
FALLBACK = {"now": "now %s, %s", "day": "%s %s to %s, %s, %s mm precipitation",
            "today": "today", "tomorrow": "tomorrow", "unknown": "weather code %s"}


def table_of(lang):
    t = LANG_DATA.get(lang) or LANG_DATA.get("en") or {}
    return t if isinstance(t, dict) else {}


def phrase(lang, key):
    v = (table_of(lang).get("phrases") or {}).get(key)
    return v if isinstance(v, str) and v else FALLBACK[key]


def word(lang, code):
    words = table_of(lang).get("codes") or {}
    w = words.get(str(code)) if isinstance(words, dict) else None
    if isinstance(w, str) and w:
        return w
    unknown = phrase(lang, "unknown")
    return unknown % code if "%s" in unknown else unknown


def deg(v):
    return "%s °C" % (round(v) if isinstance(v, (int, float)) else "?")


def at(series, i):
    return series[i] if isinstance(series, list) and i < len(series) else None


# Review M1 (fix round 1): one net under the whole call. A refusal and an
# answer leave through `emit` (SystemExit, not an Exception, so it passes);
# anything else -- a `NaN` in the forecast (`round` refuses it, and
# `allow_nan=False` keeps one out of the answer), a phrase in
# `condition_lang` with the wrong number of `%s` -- would end the script as
# `script_failed`, which carries no `hop.operation`: the exit edge
# (`hop.operation == 'weather'`) misses it, it dead-letters, and the tool
# round waits out its window. Here it is an ordinary `upstream_error`.
try:
    try:
        args = json.loads(call.get("text") or "{}")
    except Exception:
        args = None
    if not isinstance(args, dict):
        refuse("invalid_input", "the call's arguments are not a JSON object")
    place = str(args.get("place") or "").strip()
    if not place:
        refuse("invalid_input", "`place` is required: the name of a city or town")
    days = args.get("days", 1)
    # GH #1260: a whole number written as a float (`1.0`, `0.0`) is that
    # number -- JSON from a model carries no reliable int/float line, and
    # `0.0` was taken while `1.0` was refused.
    if isinstance(days, float) and days.is_integer():
        days = int(days)
    # GH #1260 (lab B-L4): a model read "days from today" as an offset and sent
    # 0 for today; the refusal sent the round to the brain. Zero is today.
    if days == 0 and not isinstance(days, bool):
        days = 1
    if isinstance(days, bool) or not isinstance(days, int) or not 1 <= days <= MAX_DAYS:
        refuse("invalid_input", "`days` is a whole number from 1 to %d" % MAX_DAYS)
    lang = str(args.get("language") or LANGUAGE).strip().lower() or "de"

    try:
        geo = get_json(GEOCODE, {"name": place, "count": 1, "language": lang, "format": "json"})
        hits = geo.get("results") if isinstance(geo, dict) else None
        if not isinstance(hits, list) or not hits or not isinstance(hits[0], dict):
            refuse("place_not_found", "no place named %s was found" % place)
        hit = hits[0]
        lat, lon = hit.get("latitude"), hit.get("longitude")
        if not isinstance(lat, (int, float)) or not isinstance(lon, (int, float)):
            refuse("place_not_found", "the place %s came back without coordinates" % place)
        fc = get_json(FORECAST, {
            "latitude": lat, "longitude": lon, "timezone": "auto", "forecast_days": days,
            "current": "temperature_2m,weather_code",
            "daily": "weather_code,temperature_2m_max,temperature_2m_min,precipitation_sum"})
    except Upstream as e:
        refuse(e.code, str(e))

    if not isinstance(fc, dict) or not isinstance(fc.get("daily"), dict):
        refuse("upstream_error", "the forecast came back without its daily series")

    name = str(hit.get("name") or place)
    country = str(hit.get("country") or "")
    where = "%s, %s" % (name, country) if country else name
    daily = fc["daily"]
    out_days = []
    for i, date in enumerate(daily.get("time") or []):
        code = at(daily.get("weather_code"), i)
        out_days.append({"date": date,
                         "temp_min": at(daily.get("temperature_2m_min"), i),
                         "temp_max": at(daily.get("temperature_2m_max"), i),
                         "precipitation_mm": at(daily.get("precipitation_sum"), i),
                         "weather_code": code, "condition": word(lang, code)})
    current = fc.get("current") if isinstance(fc.get("current"), dict) else {}
    now = None
    if current:
        now = {"time": current.get("time"), "temp": current.get("temperature_2m"),
               "weather_code": current.get("weather_code"),
               "condition": word(lang, current.get("weather_code"))}

    parts = []
    if now:
        parts.append(phrase(lang, "now") % (deg(now["temp"]), now["condition"]))
    for i, d in enumerate(out_days):
        label = (phrase(lang, "today") if i == 0 else phrase(lang, "tomorrow") if i == 1
                 else str(d["date"]))
        mm = d["precipitation_mm"] if d["precipitation_mm"] is not None else "?"
        parts.append(phrase(lang, "day") % (label, deg(d["temp_min"]), deg(d["temp_max"]),
                                  d["condition"], mm))

    # The time of the call, so a speaker can say how fresh the numbers are.
    # wall-clock: now_utc
    fetched_at = str(knob("now_utc", "")) or time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(time.time()))

    emit(json.dumps({
        "summary": "%s: %s." % (where, "; ".join(parts)),
        "place": {"name": name, "country": country, "admin1": hit.get("admin1"),
                  "latitude": lat, "longitude": lon},
        "timezone": fc.get("timezone") or hit.get("timezone"),
        "current": now,
        "days": out_days,
        "fetched_at": fetched_at,
        "source": "open-meteo",
    }, ensure_ascii=False, allow_nan=False))
except Exception as e:
    refuse("upstream_error", "the weather answer could not be read (%s)" % type(e).__name__)
